"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[32937],{28453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>a});var s=n(96540);const i={},o=s.createContext(i);function r(e){const t=s.useContext(o);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),s.createElement(o.Provider,{value:t},e.children)}},46018:(e,t,n)=>{n.d(t,{Ay:()=>h,RM:()=>r});var s=n(74848),i=n(28453),o=n(86025);const r=[];function a(e){const t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"when-facing-this-id-the-left-and-right-wear-the-same-pair-of-underwear--what-does-this-tell-us",children:"When Facing This ID, the Left and Right Wear the Same Pair of Underwear \u2014 What Does This Tell Us?"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2006/3/5 23:16:54"}),"\n"]}),"\n",(0,s.jsxs)("div",{style:{textAlign:"center"},children:[(0,s.jsx)("img",{src:(0,o.Ay)("/img/essays/leftismrightism/1.jpeg")}),(0,s.jsx)("br",{}),(0,s.jsx)("br",{})]}),"\n",(0,s.jsx)(t.p,{children:"This ID opposes the left, opposes the right, opposes the center, opposes men, opposes opposition to everything. Naturally this offends a huge number of people \u2014 absolutely nobody finds this ID agreeable. This creates the basic premise for the left and the right to frequently erupt together in incoherent babbling and sprays of white-hot text in front of this ID. But the most remarkable thing is that the left and right \u2014 who normally fight each other \u2014 can, when facing this ID, suddenly and historically unite, even sharing the same pair of underwear. What does this tell us?"}),"\n",(0,s.jsx)(t.p,{children:'As everyone knows, the left frequently slanders this ID as being a group, funded by American dollars, sent to deal with them, sent to pull down their flag. And recently, the exact same tone has appeared from the right: "Shu Nu is not a woman, nor a single person, but a state-sponsored conspiracy." It seems both left and right are born masochists, born incompetent, and both in need of things "you\'ll know when you use them." When facing this ID, the left and right wear the same pair of underwear \u2014 what does this tell us? It tells us that this ID\'s conclusion \u2014 "the left are hooligans, the right are idiots" \u2014 is correct. But it must be clarified: the hooligans are idiotic hooligans, and the idiots are hooliganish idiots. In essence, they are the same.'}),"\n",(0,s.jsx)(t.p,{children:"The left and the right are merely shriveled-seeded spherical objects growing from the same tree. Their mutual attacks, constituting a network cacophony, are nothing but shameless debauchery like stray cats in heat. They need to huddle together, they need to wave their flags, all to cover up their incompetence. The left and the right are essentially isomorphic. When one faction accuses the other of being bandits, executioners, or murderous maniacs, it's only because they themselves temporarily lack the capacity to be bandits, executioners, or murderous maniacs \u2014 and once given the opportunity, they will make up for it with a vengeance. They each have their own pretty vocabularies for attracting customers. In essence, they are no different from a certain special industry \u2014 a bunch of pitiful consumed consumers!"}),"\n",(0,s.jsx)(t.p,{children:'When facing this ID, the left and right wear the same pair of underwear. Together, the left and right have performed the ugliest, most tedious farce in human history. Good people, do not believe in any of these factions \u2014 including the so-called "centrist" deadwood, and those so-called "purists." Just look at the performances of people like Fu Sinian and Li Ao and you\'ll understand. A person must first be a person. Without independent thought, a person is not a person. All that faction-this, purist-that rubbish \u2014 let it be destroyed inhumanely!'})]})}function h(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(a,{...e})}):a(e)}},82075:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>h,default:()=>u,frontMatter:()=>a,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"timeline/essays/leftismrightism","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/essays/leftismrightism.md","sourceDirName":"timeline/essays","slug":"/timeline/essays/leftismrightism","permalink":"/timeline/essays/leftismrightism","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"leftismrightism","title":"","hide_table_of_contents":true},"sidebar":"timelineSidebar","previous":{"title":"\u82f1\u683c\u5170\uff0c\u4e22\u5f03\u8d1d\u58f3\uff0c\u8d62\u53d6\u91d1\u676f\uff01 (2006/3/5 17:22:06)","permalink":"/englandteam"},"next":{"title":"\u7f20\u4e2d\u8bf4\u7985\uff1a\u7f20\u975e\u7f20\u3001\u7985\u975e\u7985\uff0c\u67af\u6728\u9f99\u541f\u7167\u5927\u5343\uff08\u4e8c\u5341\u4e8c\uff09 (2006/3/6 10:28:35)","permalink":"/timeline/zen/22"}}');var i=n(74848),o=n(28453),r=n(46018);const a={id:"leftismrightism",title:"",hide_table_of_contents:!0},h=void 0,l={},c=[...r.RM];function d(e){return(0,i.jsx)(r.Ay,{})}function u(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d()}}}]);